insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 0, '关于空间数据结构的核心作用与本质，下列说法最准确的是？', '它是对空间数据物理模型进行逻辑抽象的结果。', '它是地理信息系统中沟通信息的桥梁，是数据逻辑模型落到物理组织方式上的实现层。', '空间数据结构仅仅影响数据的存储，不影响数据查询和分析的效率。', '对于同一种空间数据逻辑模型，只能采用唯一的空间数据结构来实现。', 'B', 'A项空间数据结构是对空间数据逻辑模型描述的数据组织关系和编排方式的具体实现，而非从物理到逻辑的抽象。 B项空间数据结构是地理信息系统沟通信息的桥梁，本质上是逻辑模型落到物理组织方式上的实现层。 C项空间数据结构对地理信息系统中数据存储、查询检索和应用分析等操作处理的效率有着至关重要的影响。 D项同一空间数据逻辑模型往往采用多种具体的空间数据结构，例如栅格数据模型可用游程长度编码或四叉树等多种结构实现。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 1, '以下关于矢量数据结构基本特点的描述中，错误的是？', '它通过记录实体坐标及其相互关系来组织地理实体，坐标空间是连续的。', '矢量数据结构具有“属性明显、位置隐含”的特点。', '传统做法是将几何图形按文件组织，属性数据采用关系型表记录并以标识符连接。', '该结构数据精度高、存储冗余较小，在计算长度、面积和形状等方面具有极高的效率。', 'B', 'A项矢量数据结构记录实体坐标，坐标空间为连续空间，这是其准确特点。 B项矢量数据结构具有“位置明显、属性隐含”的特点，而“属性明显、位置隐含”是栅格数据的特征。 C项矢量数据的传统方法正是将几何图形及其关系用文件组织，属性数据采用关系型表记录并靠标识符连接。 D项矢量数据结构精度高、数据量小，这种几何与属性分离相连的特点使其在面积、形状计算等操作中效率很高。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 2, '采用实体数据结构（Spaghetti 数据结构）组织空间数据时，存在的主要缺点是？', '数字化操作过程极其复杂，编码困难。', '无法用多边形为单元进行组织边界。', '相邻多边形的公共边界通常要数字化两遍，易造成数据冗余并可能产生缝隙或重叠。', '岛状地物会自动与外部多边形建立复杂的拓扑联系。', 'C', 'A项实体数据结构具有编码容易、数字化操作简单和数据编排直观等优点。 B项实体数据结构正是以多边形为基本单元进行组织，通过记录多边形边界的坐标来表达。 C项由于相邻多边形的公共边界要数字化两遍，从而造成数据冗余存储，且可能导致输出的公共边界出现间隙或重叠。 D项实体数据结构中，岛只作为一个单个图形，并没有建立与外界多边形的联系。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 3, '拓扑数据结构在地理信息系统中至关重要，其最重要的特征是？', '各个点坐标完全依附于面实体，不能单独存在。', '具有拓扑编辑功能，可对原始数据进行差错编辑并自动形成封闭多边形。', '不需要记录边界的起始结点和终止结点。', '采用矩阵方式排列空间实体。', 'B', 'A项拓扑数据结构的共同特点是点相互独立，点连成线，线构成面，点并非完全依附于面。 B项拓扑数据结构最重要的特征是具有拓扑编辑功能，不但能对数字化原始数据进行自动差错，而且可自动形成封闭边界。 C项拓扑结构中明确要求每条线都具有始于起始结点、止于终止结点的特征。 D项采用矩阵方式排列是栅格数据结构的特点，而非矢量拓扑结构的特征。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 4, '在索引式拓扑数据结构中，为了减少数据冗余并间接增加邻域信息，采用了什么样的结构？', '网状索引结构', '四叉树索引结构', '树状索引结构', '线性链表索引结构', 'C', 'A项索引式结构采用的不是网状索引，而是由点、线、面关系构成的树状索引。 B项四叉树结构主要用于栅格数据的压缩，与这里的矢量索引结构无关。 C项索引式数据结构采用树状索引以减少数据冗余并间接增加邻域信息。 D项该结构是由点索引与边界联系、线索引与多边形联系形成的树状结构，不是简单的线性链表。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 5, '双重独立编码结构（DIME）以哪类要素为编码主体，特别适合应用于哪类系统？', '以面为编码主体，适合森林资源管理系统', '以点为编码主体，适合气象监测系统', '以城市街道为编码主体，最适合城市信息系统', '以水系为编码主体，适合水文网络系统', 'C', 'A项DIME并非以面为编码主体，而是以线段（街道）为中心。 B项DIME强调的是线段以及左右多边形的关系，并非以纯点为主体。 C项DIME最早由美国人口统计系统采用，以城市街道为编码主体，特别适合城市信息系统与地籍管理。 D项虽然可用于网络，但DIME主要针对的是有左右多边形拓扑的网状或面状系统（如街道、宗地），非专门水系设计。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 6, '链状双重独立编码结构相对于传统 DIME 数据结构的主要改进在于？', '抛弃了拓扑关系，采用纯实体的存储方式。', '将若干直线段合为一个弧段（链段），每个弧段可以包含许多中间点。', '不再记录左右多边形的邻接关系。', '用单一网格编码代替结点坐标。', 'B', 'A项链状双重独立结构依然是拓扑数据结构，没有抛弃拓扑关系。 B项DIME中一条边只能表示两端点间的直线，而链状结构将其改进为一个可含大量中间点的弧段（链段）。 C项弧段文件仍需存储起止结点号以及左右多边形号以维持拓扑。 D项用网格编码代替坐标是矢栅一体化结构的特征，与链状DIME无关。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 7, '在复杂网络数据结构中，为了进行连通性分析，除了节点文件和边文件外，通常还必需添加什么文件？', '属性权重文件', '面域坐标文件', '节点-边关系数据文件', '栅格网格索引文件', 'C', 'A项网络分析中虽需权重属性，但连通性分析在结构层面最依赖的是拓扑关系描述。 B项网络主要由点和线组成，连通性不需要单独的面域坐标文件来支撑。 C项虽然通过节点和边文件能画出图形，但无法确定网络连通的拓扑关系，必须添加节点-边关系文件。 D项网络数据属于矢量或独立拓扑结构，不需要栅格的网格索引文件来维持连通性。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 8, '关于栅格数据结构的显著特点，表述正确的是？', '位置明显，属性隐含，通过坐标显式定位。', '能精确表达任意位置、长度和面积的连续实体。', '属性明显，定位隐含，依靠行列号转换为坐标实现定位。', '修改分辨率减小数据量时，不会损失精度和信息量。', 'C', 'A项这是矢量数据的特征，栅格数据具有“属性明显，定位隐含”的特点。 B项栅格数据表示的地表是不连续的，是量化和近似离散的数据，矢量才能任意精确定义连续实体。 C项栅格数据直接记录属性值，其位置根据在数据集中的行列号转换得出，即属性明显、定位隐含。 D项栅格数据通过改变分辨率来减少数据量时，精度和信息量会同时受损。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 9, '完全栅格数据结构的“基于像元”组织方式具有什么特点？', '坐标存储浪费极大，每个图层均要存储一遍同名坐标。', '将同一个面上所有栅格坐标统一记录一次，便于边界提取。', '节省了各图层对应坐标重复存储的空间，且便于数据扩充和修改。', '在各行数据变化时才记录数据对，具有较高压缩比。', 'C', 'A项坐标浪费大是“基于层”组织的缺点，“基于像元”方式各层对应坐标只需存储一次。 B项这是“基于面域”组织方式的特征，并非基于像元的特征。 C项基于像元是以像元为单位记录坐标及各层属性，节省了多层存储坐标的空间，简单明了，便于扩充修改。 D项这是游程长度编码的特点，完全栅格结构不采用任何压缩处理。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 10, '游程长度（行程）编码在何种情况下具有最高的压缩效率？', '当地物类型极其分散、属性连续频繁变化时。', '原始栅格类型越简单，即相邻大量像元具有相同属性时。', '当栅格图像尺寸不足 2^n × 2^n 时。', '当每个栅格单元都必须被重新加密拆分时。', 'B', 'A项压缩比与图的复杂程度成反比，变化多、类型分散的部分游程数就多，压缩效率低。 B项游程编码在相邻点有相同代码时进行压缩，原始分类越简单连续，游程越长，压缩效率就越高。 C项尺寸必须为2的幂是四叉树结构的要求，与游程编码无关。 D项虽然游程编码在栅格加密时数据量不明显增加，但其高效率根本源于像元属性的一致性而非加密操作本身。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 11, '在建立四叉树数据结构时，不断进行四等分分割的终止条件是？', '分割直到每个子区内的栅格数量为 16 个为止。', '分割直到每个子块都只含有相同的属性值或达到最小不可再分单元为止。', '分割直到所有子区的边界形成闭合多边形为止。', '分割直到背景被零填满为止。', 'B', 'A项四叉树不是以剩余像元数固定为16作为终止条件，而是看内部属性是否一致。 B项四叉树的基本思想是逐块检查，如果子块内部都含相同属性值则停止细分，直到每个块内部同质或达到最小像素。 C项这是边界表示或矢量转换的特点，与四叉树基于属性均质性的分割原则不符。 D项对于非标准图像是用0补足背景以便建树，但这并不是分割过程的停止判断条件。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 12, '线性四叉树相比于常规四叉树的主要优势是？', '保留了所有的父节点指针以便于层级回溯。', '它只存贮最后叶结点的信息（含地址码和属性），大大节省了中间指针的存储量。', '必须采用从下而上的递归合并法构建。', '它只能处理彩色遥感图像，不能处理分类专题图。', 'B', 'A项常规四叉树才保留记录父结点指针，线性四叉树省去了这些中间结点与指针。 B项线性四叉树只存贮最后叶结点的位置、深度和属性，依靠地址码（如Morton码）隐含位置信息，减小了存储量。 C项无论哪种四叉树都可以采用自上而下或自下而上建立，这并非线性四叉树独有的优势或限制。 D项线性四叉树是一种通用的数据压缩编码，既可处理图像也可处理各种分类专题栅格数据。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 13, '计算十进制 Morton 码（MD 码）的常用机制是？', '将行号和列号的十进制数直接相乘得出。', '沿顺时针方向依次将四周像素的值相加。', '将十进制的行号和列号转换成二进制数后，进行“位”的交叉组合，再转换为十进制。', '通过求同一层级中所有相邻格网的平均值产生。', 'C', 'A项Morton码不是通过行列的十进制直接乘积运算生成的。 B项顺时针方向搜索是链码或某些拓扑追踪的方法，与Morton码的“位”操作无关。 C项根据算法，需先将行列号转为二进制数，并两两交叉错位产生新的二进制数，再转化为十进制得出MD码。 D项平均值计算适用于栅格重采样降尺度，与产生Morton地址码无关。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 14, '二维行程编码结构的实质是？', '对原始栅格逐行扫描进行一维的游程压缩。', '把常规游程编码直接应用到矢量数据上。', '在线性四叉树生成后，进一步将前后地址码相邻且属性值相同的叶结点合并。', '彻底抛弃了 Morton 码排序，重新生成随机列表。', 'C', 'A项逐行扫描并压缩是传统的一维游程长度编码，不是二维行程编码。 B项二维行程编码仍是针对栅格数据的压缩方式，未应用到矢量数据。 C项它在线性四叉树表列的基础上，对按 Morton 码排序后相邻且属性值相同的叶结点进行再次合并，进一步压缩了数据。 D项它严格采用了线性四叉树的地址码（Morton 码）的顺序进行编码，而非随机列表。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 15, '采用 Freeman 码的链码数据结构具有什么明显的缺点？', '无法记录对象的起始点和方向链。', '对计算面积、长度和凹凸度极为不便。', '没有区域性质，对边界的合并、插入等修改编辑十分困难，不适于复杂的区域空间分析。', '会造成大量的空白冗余存储，压缩效率最低。', 'C', 'A项链式编码恰恰是由起始点和单位矢量链组成，清晰记录了起点和方向。 B项链码结构对计算面积、长度、转折方向等几何特征实际上是十分方便的。 C项由于链码结构不具有区域填充性质，对其进行边界编辑修改困难，也不便于执行区域性的空间分析运算。 D项链码能将线状与边界数据大幅度压缩为少量链码串，不存在大量空白冗余的问题。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 16, '在影像与瓦片金字塔数据结构中，各层级分辨率的分布规律是？', '金字塔的最顶层存储最高分辨率数据，底层存储最低分辨率数据。', '所有层级的分辨率完全相同，只改变每张切片覆盖的面积。', '金字塔最顶层存储最低分辨率、数据量最小的影像；到底层则存储分辨率最高、数据量最大的影像。', '切片的层级数量不影响数据的总体压缩比例。', 'C', 'A项顶层应该存放最低分辨率的数据，底层才是最高分辨率数据。 B项金字塔的不同层级代表着由粗到细的不同分辨率阶段，分辨率随层级改变。 C项最顶层数据量小、分辨率低；随着层数往下，数据分辨率逐步变细，直到满足底层高清需求。 D项金字塔本身是为了有损压缩和快显，层级的设置与压缩传输效率密切相关。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 17, '现代互联网地图使用瓦片（切片）金字塔的主要作用是？', '提升矢量拓扑检查的速度。', '使不同显示比例尺等级下的用户请求都能看到固定大小但具有相同清晰分辨率的地图切片，提升传输效率。', '使得遥感影像能够被彻底转化为纯矢量数据。', '对不规则镶嵌模型（如 TIN）进行重新划分。', 'B', 'A项切片主要用于数据组织、传输和快速显示，与矢量拓扑检查速度无关。 B项互联网地图将数据组织为多级切片，确保放大缩小时加载的总是对应级别的清晰小图块，避免直接传输大文件。 C项瓦片机制不仅适用于影像，也适用于电子地图切图，但并不涉及栅格与矢量的实质性数据格式转换。 D项瓦片金字塔常用于按规则四等分进行组织的影像和地图，与 TIN 不规则镶嵌无关。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 18, '相对于栅格数据结构，传统矢量数据结构在应用中存在的一个主要缺点是？', '图形绘制和输出极其粗糙。', '数据存储量极其庞大，存在巨大的数据冗余。', '数学模拟较为困难，且在执行叠置分析等操作时算法处理非常复杂。', '极难建立和管理空间网络拓扑关系。', 'C', 'A项矢量数据具有“图形显示质量好、精度高、输出美观”的优点。 B项矢量数据的特点就是数据结构严密，冗余度小，数据量相对较小。 C项由于矢量坐标的复杂性，它在处理图层叠置分析和连续场数学模拟时，相较于栅格矩阵要复杂得多。 D项矢量数据极易构建网络拓扑关系，相反，栅格结构难以建立网络连接关系。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 19, '在矢栅一体化数据结构中，通过多级格网来实现数据的空间定位。其中 M0、M1、M2 的具体作用是？', '分别代表三种不同颜色的属性编码。', 'M0、M1 表示研究区整体的粗格网和基本格网 Morton 码，M2 表示基本栅格内的细分格网局部 Morton 码。', 'M0 代表点实体，M1 代表线实体，M2 代表面实体。', 'M0、M1、M2 是矢量数据的平面直角坐标系的分量。', 'B', 'A项M 码（Morton码）用于表示空间空间格网索引位置，而非颜色属性编码。 B项M0 对应粗格网整体编码，M1 对应基本格网整体编码，M2 对应为提高分辨率细分的局部格网编码，以此构建多级结构。 C项点、线、面实体都需使用多级格网组合（如M1, M2序列）来描述其定位或填充，并不分别对应单一的 M 层。 D项M 码是基于栅格四叉树思想生成的地址索引，是用来“代替”矢量直角坐标的，而非直角坐标分量。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 20, '矢栅一体化数据结构为赋予栅格结构矢量特性，对空间对象做出了三个约定，下列哪个不属于这三个约定？', '点状地物仅有空间位置而无形状和面积，计算机中仅保留一个坐标数据（M1, M2）。', '线状地物有形状但无面积，用一组填满栅格元子的路径来表达。', '面状地物有形状和面积，由元子表达边界线以及内部被填满的区域组成。', '所有地物的拓扑关系都必须用 Spaghetti 链表单独重写。', 'D', 'A项约定之一确实是点实体只记录位置（转换后的格网坐标）。 B项约定之二定义线状地物用一组格网元子填充的路径表示。 C项约定之三定义面状地物除了边界线外，还要用内部被填满的元子区域表达。 D项矢栅一体化自带网格拓扑特性，通过记录穿过网格边界的指针维持关系，并非使用非拓扑的 Spaghetti 重写。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 21, '在矢量点数据向栅格数据结构转换时，如果多个点对象落入同一个目标栅格像元中，通常如何处理其像元值？', '强制丢弃所有点对象，将像元设为无数据（NoData）。', '必须采用所有要素属性值的最小值赋给该栅格。', '可以根据实际需要采用值总和、平均值、最大值、最小值或众数等不同的赋值原则进行计算。', '自动对栅格单元进行四叉树分裂直到每一个像元只包含一个点。', 'C', 'A项丢弃数据是不合理的，系统提供了多种冲突解决机制以保留信息。 B项取最小值只是一种可选原则，并非唯一的“必须”准则。 C项矢转栅时，多个点落入同一单元的情况，通常可按总和、平均值、极值、众数等统计规则计算出最终的像元值。 D项栅格分辨率（像元大小）在转换前已固定好，一般不会在转换运算中途自动进行动态四叉树分裂。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 22, '矢量多边形向栅格转换（即多边形栅格化）的核心操作是首先栅格化边界线段，然后用属性值填充面域内部。下列哪种算法不是常用的多边形填充算法？', '内部点扩散法', '射线法', '扫描线法', '样条函数插值法', 'D', 'A项内部点扩散（如泛洪填充）是经典的面域栅格化填充算法。 B项射线法能判断格网点是否在面域内，是常用的填充判断算法。 C项扫描线法通过水平线与边界交点来判定并填充内部栅格，极为常用。 D项样条函数插值法用于栅格转矢量后的曲线圆滑去锯齿操作，不是用于多边形栅格填充。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 23, '将图幅从自动扫描仪获取的栅格数据转换为矢量数据时，通常需要经历一系列复杂处理。下列哪个步骤属于正常的栅格转矢量处理流程？', '降低原图分辨率以掩盖数字化误差。', '将彩色影像直接转为带有三维拓扑的网状结构。', '经过二值化、细化处理，顺时针或逆时针根据8邻域搜索跟踪线段，生成拓扑并去除多余点。', '对线画图应用内部点扩散法进行内部填充。', 'C', 'A项降分辨率会进一步损失图形质量，正确做法应是在原有提取基础上细化和拟合。 B项栅格转矢量前需要提取边界和二值化，且不是直接产生三维网状结构。 C项标准的栅格转矢量过程包括边界提取/细化成二值图，通过8邻域搜索跟踪，坐标转换，建立拓扑，最后去冗余与圆滑。 D项内部点扩散法是将矢量面转为栅格时用的填充算法，方向恰好相反。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 24, '由于栅格精度限制，栅格数据矢量化生成的追踪曲线往往不够圆滑，存在锯齿。下列用于曲线圆滑（插补平滑处理）的算法是？', '分段三次多项式插值法与样条函数插值法。', '游程长度编码算法。', 'DIME 拓扑建网法。', '粗格网与基本格网融合法。', 'A', 'A项为了平滑去锯齿，常用线性迭代、分段三次多项式插值、样条函数插值法等。 B项游程长度编码是栅格数据的无损压缩结构算法。 C项DIME 是建立网络或多边形拓扑数据结构的方式，无插值圆滑功能。 D项粗细格网融合是矢栅一体化数据组织的机制。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 25, '以 Voronoi 单元为核心组织不规则镶嵌数据时，其结构的显著特点包括？', '用正方形或矩形单元进行平面的规则划分。', '相邻 Voronoi 单元的边界定义为相邻样点连线的垂直平分线，数据表统一按逆时针记录相邻关系。', '只记录顶点坐标，不需要建立样点ID、单元顶点组成的映射。', '它本质上等同于完全栅格数据结构的基于像元方式。', 'B', 'A项Voronoi 是不规则多边形面块，规则正方形单元属于普通栅格模型。 B项Voronoi图依据相邻节点连线的垂直平分线生成边界，并以逆时针记录单元邻接与顶点组成以支持空间面域分析。 C项结构中包含详尽的样点记录、邻接表、顶点坐标及单元-顶点组成表，联系十分紧密。 D项它是基于矢量坐标和多边形边界构筑的不规则镶嵌拓扑结构，与逐个格网的完全栅格完全不同。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 26, 'TIN 三角网可以使用两种不同的核心对象建立拓扑。若以“特征结点”为基本空间对象组织 TIN 数据结构，其文件的主要特征是？', '每个三角形记录一条包含三个顶点的长链。', '通过正方形栅格来替代特征点位置。', '顶点文件中增加了指针，利用另一索引文件按顺时针指向与该点相连接的所有其余特征点。', '自动省略所有的边界连线。', 'C', 'A项这是以“三角形”为基本对象组织时的表现形式。 B项TIN 是矢量的不规则三角网，不使用正方形栅格替代点。 C项以结点为核心的TIN结构，使用顶点附加指针，指向顺时针排列的相邻点连线索引表，极适合边和点的连接推理（如插值）。 D项TIN通过点或三角形建立完整的全覆盖连接，边界连线必不可少。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 27, '时空数据模型与三维数据模型（X, Y, Z）虽然在多维表示形式上有类似之处，但两者存在本质上的逻辑与分析差异，其根本原因是？', '三维数据通常存储为矢量，而时空数据只能存储为游程编码栅格。', '三维数据模型的三个维度都只能表示离散数据，时空模型只能表示连续场。', '三维空间中三个维度的度量尺度和单位是一致的（均表示空间距离），而时空模型中 T 轴的度量单位是特定的时间长度，与其他两轴尺度不一致。', '时空数据模型只需要在文件头部加入一个统一时间戳即可，不需要 T 轴。', 'C', 'A项两者既可以用离散对象表达，也可以用连续场等多种结构表达，存储方式不局限。 B项两种模型都既包含离散数据形式也包含连续形式。 C项这是导致二者分析范式和算法不同的根源，T 轴代表的是时间维，其度量衡与代表空间距离的 XY(Z) 轴截然不同。 D项要对动态变化进行分析建模，T 作为独立维度深度参与内部结构划分，不仅是单一头部属性。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 28, '八叉树数据结构在处理三维空间物体时，其主要优点之一是？', '由于彻底清除了树状层级结构，节省了极大的指针空间。', '它强制将空间分割为 10 等分，具有更高的表达精度。', '只能应用于没有内部属性变化的空间物体。', '非常方便实现空间对象的并、交、差等集合运算，并有助于消除隐线和隐面。', 'D', 'A项八叉树依靠逐级划分的层级结构组织，并未清除树状层级。 B项顾名思义并依定义，八叉树是将三维空间沿三个方向从中间八等分。 C项八叉树正是用来刻画三维内部属性随空间变化分布的体素模型。 D项基于八叉树规则严谨的有序性和分层性，集合运算极其方便，也有助于三维显示的隐面消除平衡。', datetime('now'));
insert into exercises (chapter_id, exercise_index, question, option_a, option_b, option_c, option_d, correct_answer, explanation, updated_at) values ('chapter-4', 29, '采用三维边界表示法来描述三维平面多面体时，为了更充分地表达拓扑关系以用“空间换取时间”，通常会对基础数据表进行什么扩充？', '将多面体投影为二维 DIME 文件。', '在边表或面表中加入所属相邻多边形的信息（如指出某条边是否为两个多边形公共边），以便快速检索。', '利用游程长度对三维多面体的顶点坐标进行压缩。', '丢弃顶点表，只保留纯面表文件。', 'B', 'A项二维 DIME 是平面网状编码，不涉及三维表面多面体的空间换时间扩充。 B项在边表中补充指出它是由哪两个多边形共享的公共边，避免在查询时重复计算，极大地提高了面与面相邻拓扑关系的处理效率。 C项游程编码用于栅格矩阵压缩，不适用于基于点、边、面的矢量三维边界表示法。 D项三维边界表示法的核心是避免点、边、面的重复，省略顶点表将导致公共顶点坐标被反复多次重复记录，背离其初衷。', datetime('now'));
